from pathlib import Path
import subprocess
repo=Path('/Users/steventran/jobpipe')
def command(args,timeout=12):
 try:
  p=subprocess.run(args,cwd=repo,text=True,capture_output=True,timeout=timeout)
  print('COMMAND',args,'EXIT',p.returncode,'STDOUT',p.stdout[-4200:],'STDERR',p.stderr[-500:])
 except Exception as e:print('COMMAND_ERROR',args,type(e).__name__,str(e)[:300])
command(['git','rev-parse','HEAD'])
command(['git','status','--short'])
command(['ps','-axo','pid,ppid,stat,%cpu,%mem,etime,command'])
