 for i,line in enumerate(lines):
  if any(k in line for k in ['set_default_timeout','set_content','async_playwright','browser.new_page','@pytest.fixture','def load_fixture','def page(','pytest_plugins','timeout=2000']):
   print('HIT',i+1,' '.join(s.strip() for s in lines[max(0,i-4):min(len(lines),i+8)])[:720])
